UPDATE public.rooms SET exits=exits || '{"east": "high-sanctum-market-street"}'::jsonb, description=description || ' East, the shopping street leads to weapons, armor, spell books, provisions, workshops and homes.' WHERE slug='high-sanctum' AND NOT (exits @> '{"east": "high-sanctum-market-street"}'::jsonb);
UPDATE public.rooms SET exits=exits || '{"north": "high-sanctum-residential-walk"}'::jsonb WHERE slug='sanctum-rest-house' AND NOT (exits ? 'north');
UPDATE public.rooms SET exits=exits || '{"east": "iron-bastion-market-street"}'::jsonb, description=description || ' East, the shopping street leads to weapons, armor, spell books, provisions, workshops and homes.' WHERE slug='iron-bastion' AND NOT (exits @> '{"east": "iron-bastion-market-street"}'::jsonb);
UPDATE public.rooms SET exits=exits || '{"north": "iron-bastion-residential-walk"}'::jsonb WHERE slug='bastion-billet' AND NOT (exits ? 'north');
UPDATE public.rooms SET exits=exits || '{"east": "mirrorlands-court-market-street"}'::jsonb, description=description || ' East, the shopping street leads to weapons, armor, spell books, provisions, workshops and homes.' WHERE slug='mirrorlands-court' AND NOT (exits @> '{"east": "mirrorlands-court-market-street"}'::jsonb);
UPDATE public.rooms SET exits=exits || '{"north": "mirrorlands-court-residential-walk"}'::jsonb WHERE slug='mirror-rest-house' AND NOT (exits ? 'north');
UPDATE public.rooms SET exits=exits || '{"east": "gilded-bazaar-market-street"}'::jsonb, description=description || ' East, the shopping street leads to weapons, armor, spell books, provisions, workshops and homes.' WHERE slug='gilded-bazaar' AND NOT (exits @> '{"east": "gilded-bazaar-market-street"}'::jsonb);
UPDATE public.rooms SET exits=exits || '{"north": "gilded-bazaar-residential-walk"}'::jsonb WHERE slug='bazaar-caravanserai' AND NOT (exits ? 'north');
UPDATE public.rooms SET exits=exits || '{"east": "silent-horizon-market-street"}'::jsonb, description=description || ' East, the shopping street leads to weapons, armor, spell books, provisions, workshops and homes.' WHERE slug='silent-horizon' AND NOT (exits @> '{"east": "silent-horizon-market-street"}'::jsonb);
UPDATE public.rooms SET exits=exits || '{"north": "silent-horizon-residential-walk"}'::jsonb WHERE slug='horizon-dormitory' AND NOT (exits ? 'north');
UPDATE public.rooms SET exits=exits || '{"east": "evershade-court-market-street"}'::jsonb, description=description || ' East, the shopping street leads to weapons, armor, spell books, provisions, workshops and homes.' WHERE slug='evershade-court' AND NOT (exits @> '{"east": "evershade-court-market-street"}'::jsonb);
UPDATE public.rooms SET exits=exits || '{"north": "evershade-court-residential-walk"}'::jsonb WHERE slug='evershade-rest' AND NOT (exits ? 'north');
UPDATE public.rooms SET exits=exits || '{"east": "feastlands-keep-market-street"}'::jsonb, description=description || ' East, the shopping street leads to weapons, armor, spell books, provisions, workshops and homes.' WHERE slug='feastlands-keep' AND NOT (exits @> '{"east": "feastlands-keep-market-street"}'::jsonb);
UPDATE public.rooms SET exits=exits || '{"north": "feastlands-keep-residential-walk"}'::jsonb WHERE slug='keep-bunkhouse' AND NOT (exits ? 'north');
WITH RECURSIVE reach(capital,slug) AS (SELECT slug,slug FROM public.rooms WHERE slug IN ('high-sanctum','iron-bastion','mirrorlands-court','gilded-bazaar','silent-horizon','evershade-court','feastlands-keep') UNION SELECT reach.capital,e.value FROM reach JOIN public.rooms r ON r.slug=reach.slug CROSS JOIN LATERAL jsonb_each_text(r.exits) e JOIN public.rooms d ON d.slug=e.value WHERE d.kind NOT IN ('gate','capital') AND d.requires_faction IS NULL AND NOT d.hidden AND (d.town_key IS NULL OR d.town_key=reach.capital)), ownership AS (SELECT slug,min(capital) capital FROM reach GROUP BY slug HAVING count(DISTINCT capital)=1) UPDATE public.rooms r SET town_key=o.capital FROM ownership o WHERE r.slug=o.slug AND r.town_key IS NULL;