INSERT INTO public.rooms (slug,name,description,ambience,exits,kind,label,town_key) VALUES ('high-sanctum-market-street','Censer Street','White stone arcades carry censers above the crowds; named flames burn at every lintel. Weapons are displayed beneath a crossed-blade sign to the north. Books and rune charts fill the windows to the south. The workshops continue east; the central square lies west.','White stone arcades carry censers above the crowds; named flames burn at every lintel.','{"west": "high-sanctum", "east": "high-sanctum-artisan-lane", "north": "high-sanctum-weapon-shop", "south": "high-sanctum-arcana-shop"}'::jsonb,'road','Censer Street','high-sanctum') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.rooms (slug,name,description,ambience,exits,kind,label,town_key) VALUES ('high-sanctum-artisan-lane','Sunhammer Lane','White stone arcades carry censers above the crowds; named flames burn at every lintel. Armor hangs in the northern shop windows. Baskets of food, tools and medicines stand in the southern doorway. Homes lie east and the market street west.','White stone arcades carry censers above the crowds; named flames burn at every lintel.','{"west": "high-sanctum-market-street", "east": "high-sanctum-residential-walk", "north": "high-sanctum-armor-shop", "south": "high-sanctum-provision-shop"}'::jsonb,'road','Sunhammer Lane','high-sanctum') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.rooms (slug,name,description,ambience,exits,kind,label,town_key) VALUES ('high-sanctum-residential-walk','Pilgrims'' Terrace','White stone arcades carry censers above the crowds; named flames burn at every lintel. Residents share news on their doorsteps. The civic house stands north, and the inn opens south. The workshops are west.','White stone arcades carry censers above the crowds; named flames burn at every lintel.','{"west": "high-sanctum-artisan-lane", "north": "high-sanctum-civic-house", "south": "sanctum-rest-house"}'::jsonb,'road','Pilgrims'' Terrace','high-sanctum') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.rooms (slug,name,description,ambience,exits,kind,label,town_key) VALUES ('high-sanctum-civic-house','Witness House','White stone arcades carry censers above the crowds; named flames burn at every lintel. A clerk records local affairs beside benches where residents discuss work, journeys and grievances. The residential street is south.','White stone arcades carry censers above the crowds; named flames burn at every lintel.','{"south": "high-sanctum-residential-walk"}'::jsonb,'hall','Witness House','high-sanctum') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.rooms (slug,name,description,ambience,exits,kind,label,town_key) VALUES ('high-sanctum-weapon-shop','The Beacon''s Edge','White stone arcades carry censers above the crowds; named flames burn at every lintel. Racks hold swords, bows, axes and other usable weapons, each carefully weighed and priced. The merchant buys suitable loot as well. The market street is south.','White stone arcades carry censers above the crowds; named flames burn at every lintel.','{"south": "high-sanctum-market-street"}'::jsonb,'shop','The Beacon''s Edge','high-sanctum') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.rooms (slug,name,description,ambience,exits,kind,label,town_key) VALUES ('high-sanctum-armor-shop','Gilded Mail House','White stone arcades carry censers above the crowds; named flames burn at every lintel. Mail, plate, shields and fitted armor line the walls. The armorer measures a customer beside a polished shield. The workshop lane is south.','White stone arcades carry censers above the crowds; named flames burn at every lintel.','{"south": "high-sanctum-artisan-lane"}'::jsonb,'shop','Gilded Mail House','high-sanctum') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.rooms (slug,name,description,ambience,exits,kind,label,town_key) VALUES ('high-sanctum-arcana-shop','The Lit Folio','White stone arcades carry censers above the crowds; named flames burn at every lintel. Rune-teaching spell books, scrolls and magical foci are displayed under glass. The bookseller keeps the prices in an open ledger. The market street is north.','White stone arcades carry censers above the crowds; named flames burn at every lintel.','{"north": "high-sanctum-market-street"}'::jsonb,'shop','The Lit Folio','high-sanctum') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.rooms (slug,name,description,ambience,exits,kind,label,town_key) VALUES ('high-sanctum-provision-shop','The Pilgrim''s Pantry','White stone arcades carry censers above the crowds; named flames burn at every lintel. Food, potions, gathering tools and crafting supplies fill the shelves. A kettle steams beside the counter. The workshop lane is north.','White stone arcades carry censers above the crowds; named flames burn at every lintel.','{"north": "high-sanctum-artisan-lane"}'::jsonb,'shop','The Pilgrim''s Pantry','high-sanctum') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.npcs (room,home_room,name,title,persona,greeting,is_merchant,merchant_town,merchant_categories) SELECT 'high-sanctum-weapon-shop','high-sanctum-weapon-shop','Seren Dawnsteel','weaponsmith','A working weaponsmith who explains weapons and buys appropriate loot. Lives in high-sanctum, the living capital of Solastin. White stone arcades carry censers above the crowds; named flames burn at every lintel. Directions: from the central square go east to Censer Street; north for weapons, south for arcana; east again for armor north and provisions south; further east for homes, civic house north and inn south. Never claim that the kingdoms have fallen.','Welcome to The Beacon''s Edge.',true,'high-sanctum',ARRAY['weapon','arms']::text[] WHERE NOT EXISTS (SELECT 1 FROM public.npcs WHERE name='Seren Dawnsteel');
