INSERT INTO public.npcs (room,home_room,name,title,persona,greeting,is_merchant,merchant_town,merchant_categories) SELECT 'mirrorlands-court-residential-walk','mirrorlands-court-residential-walk','Cyran Newface','local resident','A resident who knows local streets and buildings and has a personal life beyond the player. Lives in mirrorlands-court, the living capital of Nyxara. Pale roofs and mirrored canals double the moving crowd; artists hang freshly painted faces beside their doors. Directions: from the central square go east to Glasslight Street; north for weapons, south for arcana; east again for armor north and provisions south; further east for homes, civic house north and inn south. Never claim that the kingdoms have fallen.','Welcome to Reflections Terrace.',false,NULL,ARRAY[]::text[] WHERE NOT EXISTS (SELECT 1 FROM public.npcs WHERE name='Cyran Newface');
INSERT INTO public.npcs (room,home_room,name,title,persona,greeting,is_merchant,merchant_town,merchant_categories) SELECT 'mirrorlands-court-civic-house','mirrorlands-court-civic-house','Maelis Namekeeper','civic clerk','A civic clerk who discusses the city and points travelers toward shops, inns, banks and guildmasters. Lives in mirrorlands-court, the living capital of Nyxara. Pale roofs and mirrored canals double the moving crowd; artists hang freshly painted faces beside their doors. Directions: from the central square go east to Glasslight Street; north for weapons, south for arcana; east again for armor north and provisions south; further east for homes, civic house north and inn south. Never claim that the kingdoms have fallen.','Welcome to The Naming House.',false,NULL,ARRAY[]::text[] WHERE NOT EXISTS (SELECT 1 FROM public.npcs WHERE name='Maelis Namekeeper');
INSERT INTO public.rooms (slug,name,description,ambience,exits,kind,label,town_key) VALUES ('gilded-bazaar-market-street','Saffron Street','Gold-leaf awnings shelter scales, bright textiles and food stalls; porters weave between coin-counting customers. Weapons are displayed beneath a crossed-blade sign to the north. Books and rune charts fill the windows to the south. The workshops continue east; the central square lies west.','Gold-leaf awnings shelter scales, bright textiles and food stalls; porters weave between coin-counting customers.','{"west": "gilded-bazaar", "east": "gilded-bazaar-artisan-lane", "north": "gilded-bazaar-weapon-shop", "south": "gilded-bazaar-arcana-shop"}'::jsonb,'road','Saffron Street','gilded-bazaar') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.rooms (slug,name,description,ambience,exits,kind,label,town_key) VALUES ('gilded-bazaar-artisan-lane','Coinwright Lane','Gold-leaf awnings shelter scales, bright textiles and food stalls; porters weave between coin-counting customers. Armor hangs in the northern shop windows. Baskets of food, tools and medicines stand in the southern doorway. Homes lie east and the market street west.','Gold-leaf awnings shelter scales, bright textiles and food stalls; porters weave between coin-counting customers.','{"west": "gilded-bazaar-market-street", "east": "gilded-bazaar-residential-walk", "north": "gilded-bazaar-armor-shop", "south": "gilded-bazaar-provision-shop"}'::jsonb,'road','Coinwright Lane','gilded-bazaar') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.rooms (slug,name,description,ambience,exits,kind,label,town_key) VALUES ('gilded-bazaar-residential-walk','Caravan Terrace','Gold-leaf awnings shelter scales, bright textiles and food stalls; porters weave between coin-counting customers. Residents share news on their doorsteps. The civic house stands north, and the inn opens south. The workshops are west.','Gold-leaf awnings shelter scales, bright textiles and food stalls; porters weave between coin-counting customers.','{"west": "gilded-bazaar-artisan-lane", "north": "gilded-bazaar-civic-house", "south": "bazaar-caravanserai"}'::jsonb,'road','Caravan Terrace','gilded-bazaar') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.rooms (slug,name,description,ambience,exits,kind,label,town_key) VALUES ('gilded-bazaar-civic-house','The Brokers'' House','Gold-leaf awnings shelter scales, bright textiles and food stalls; porters weave between coin-counting customers. A clerk records local affairs beside benches where residents discuss work, journeys and grievances. The residential street is south.','Gold-leaf awnings shelter scales, bright textiles and food stalls; porters weave between coin-counting customers.','{"south": "gilded-bazaar-residential-walk"}'::jsonb,'hall','The Brokers'' House','gilded-bazaar') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.rooms (slug,name,description,ambience,exits,kind,label,town_key) VALUES ('gilded-bazaar-weapon-shop','The Golden Edge','Gold-leaf awnings shelter scales, bright textiles and food stalls; porters weave between coin-counting customers. Racks hold swords, bows, axes and other usable weapons, each carefully weighed and priced. The merchant buys suitable loot as well. The market street is south.','Gold-leaf awnings shelter scales, bright textiles and food stalls; porters weave between coin-counting customers.','{"south": "gilded-bazaar-market-street"}'::jsonb,'shop','The Golden Edge','gilded-bazaar') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.rooms (slug,name,description,ambience,exits,kind,label,town_key) VALUES ('gilded-bazaar-armor-shop','Coinshield Outfitters','Gold-leaf awnings shelter scales, bright textiles and food stalls; porters weave between coin-counting customers. Mail, plate, shields and fitted armor line the walls. The armorer measures a customer beside a polished shield. The workshop lane is south.','Gold-leaf awnings shelter scales, bright textiles and food stalls; porters weave between coin-counting customers.','{"south": "gilded-bazaar-artisan-lane"}'::jsonb,'shop','Coinshield Outfitters','gilded-bazaar') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.rooms (slug,name,description,ambience,exits,kind,label,town_key) VALUES ('gilded-bazaar-arcana-shop','The Gilded Folio','Gold-leaf awnings shelter scales, bright textiles and food stalls; porters weave between coin-counting customers. Rune-teaching spell books, scrolls and magical foci are displayed under glass. The bookseller keeps the prices in an open ledger. The market street is north.','Gold-leaf awnings shelter scales, bright textiles and food stalls; porters weave between coin-counting customers.','{"north": "gilded-bazaar-market-street"}'::jsonb,'shop','The Gilded Folio','gilded-bazaar') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.rooms (slug,name,description,ambience,exits,kind,label,town_key) VALUES ('gilded-bazaar-provision-shop','The Caravan Pantry','Gold-leaf awnings shelter scales, bright textiles and food stalls; porters weave between coin-counting customers. Food, potions, gathering tools and crafting supplies fill the shelves. A kettle steams beside the counter. The workshop lane is north.','Gold-leaf awnings shelter scales, bright textiles and food stalls; porters weave between coin-counting customers.','{"north": "gilded-bazaar-artisan-lane"}'::jsonb,'shop','The Caravan Pantry','gilded-bazaar') ON CONFLICT (slug) DO NOTHING;
