INSERT INTO public.rooms (slug,name,description,ambience,exits,kind,label,town_key) VALUES ('evershade-court-arcana-shop','The Candlebound Folio','White timber houses frame ribbon-hung balconies; candle makers and singers share streets fragrant with wax and flowers. Rune-teaching spell books, scrolls and magical foci are displayed under glass. The bookseller keeps the prices in an open ledger. The market street is north.','White timber houses frame ribbon-hung balconies; candle makers and singers share streets fragrant with wax and flowers.','{"north": "evershade-court-market-street"}'::jsonb,'shop','The Candlebound Folio','evershade-court') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.rooms (slug,name,description,ambience,exits,kind,label,town_key) VALUES ('evershade-court-provision-shop','The Lantern Pantry','White timber houses frame ribbon-hung balconies; candle makers and singers share streets fragrant with wax and flowers. Food, potions, gathering tools and crafting supplies fill the shelves. A kettle steams beside the counter. The workshop lane is north.','White timber houses frame ribbon-hung balconies; candle makers and singers share streets fragrant with wax and flowers.','{"north": "evershade-court-artisan-lane"}'::jsonb,'shop','The Lantern Pantry','evershade-court') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.npcs (room,home_room,name,title,persona,greeting,is_merchant,merchant_town,merchant_categories) SELECT 'evershade-court-weapon-shop','evershade-court-weapon-shop','Ravel Vowsteel','weaponsmith','A working weaponsmith who explains weapons and buys appropriate loot. Lives in evershade-court, the living capital of Velithria. White timber houses frame ribbon-hung balconies; candle makers and singers share streets fragrant with wax and flowers. Directions: from the central square go east to Votive Street; north for weapons, south for arcana; east again for armor north and provisions south; further east for homes, civic house north and inn south. Never claim that the kingdoms have fallen.','Welcome to The Vowed Edge.',true,'evershade-court',ARRAY['weapon','arms']::text[] WHERE NOT EXISTS (SELECT 1 FROM public.npcs WHERE name='Ravel Vowsteel');
INSERT INTO public.npcs (room,home_room,name,title,persona,greeting,is_merchant,merchant_town,merchant_categories) SELECT 'evershade-court-armor-shop','evershade-court-armor-shop','Elira Threadguard','armorer','An armorer who fits armor and shields and trades jewelry. Lives in evershade-court, the living capital of Velithria. White timber houses frame ribbon-hung balconies; candle makers and singers share streets fragrant with wax and flowers. Directions: from the central square go east to Votive Street; north for weapons, south for arcana; east again for armor north and provisions south; further east for homes, civic house north and inn south. Never claim that the kingdoms have fallen.','Welcome to Silksteel Outfitters.',true,'evershade-court',ARRAY['armor','gem']::text[] WHERE NOT EXISTS (SELECT 1 FROM public.npcs WHERE name='Elira Threadguard');
