INSERT INTO public.npcs (room,home_room,name,title,persona,greeting,is_merchant,merchant_town,merchant_categories) SELECT 'evershade-court-residential-walk','evershade-court-residential-walk','Nimel Lanternsong','local resident','A resident who knows local streets and buildings and has a personal life beyond the player. Lives in evershade-court, the living capital of Velithria. White timber houses frame ribbon-hung balconies; candle makers and singers share streets fragrant with wax and flowers. Directions: from the central square go east to Votive Street; north for weapons, south for arcana; east again for armor north and provisions south; further east for homes, civic house north and inn south. Never claim that the kingdoms have fallen.','Welcome to Lantern Terrace.',false,NULL,ARRAY[]::text[] WHERE NOT EXISTS (SELECT 1 FROM public.npcs WHERE name='Nimel Lanternsong');
INSERT INTO public.npcs (room,home_room,name,title,persona,greeting,is_merchant,merchant_town,merchant_categories) SELECT 'evershade-court-civic-house','evershade-court-civic-house','Tessia Promisequill','civic clerk','A civic clerk who discusses the city and points travelers toward shops, inns, banks and guildmasters. Lives in evershade-court, the living capital of Velithria. White timber houses frame ribbon-hung balconies; candle makers and singers share streets fragrant with wax and flowers. Directions: from the central square go east to Votive Street; north for weapons, south for arcana; east again for armor north and provisions south; further east for homes, civic house north and inn south. Never claim that the kingdoms have fallen.','Welcome to The Promise House.',false,NULL,ARRAY[]::text[] WHERE NOT EXISTS (SELECT 1 FROM public.npcs WHERE name='Tessia Promisequill');
INSERT INTO public.rooms (slug,name,description,ambience,exits,kind,label,town_key) VALUES ('feastlands-keep-market-street','Harvest Street','Living roots brace broad timber halls; growers, hunters and cooks fill the streets beneath baskets of ripening fruit. Weapons are displayed beneath a crossed-blade sign to the north. Books and rune charts fill the windows to the south. The workshops continue east; the central square lies west.','Living roots brace broad timber halls; growers, hunters and cooks fill the streets beneath baskets of ripening fruit.','{"west": "feastlands-keep", "east": "feastlands-keep-artisan-lane", "north": "feastlands-keep-weapon-shop", "south": "feastlands-keep-arcana-shop"}'::jsonb,'road','Harvest Street','feastlands-keep') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.rooms (slug,name,description,ambience,exits,kind,label,town_key) VALUES ('feastlands-keep-artisan-lane','Rootwright Lane','Living roots brace broad timber halls; growers, hunters and cooks fill the streets beneath baskets of ripening fruit. Armor hangs in the northern shop windows. Baskets of food, tools and medicines stand in the southern doorway. Homes lie east and the market street west.','Living roots brace broad timber halls; growers, hunters and cooks fill the streets beneath baskets of ripening fruit.','{"west": "feastlands-keep-market-street", "east": "feastlands-keep-residential-walk", "north": "feastlands-keep-armor-shop", "south": "feastlands-keep-provision-shop"}'::jsonb,'road','Rootwright Lane','feastlands-keep') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.rooms (slug,name,description,ambience,exits,kind,label,town_key) VALUES ('feastlands-keep-residential-walk','Orchard Terrace','Living roots brace broad timber halls; growers, hunters and cooks fill the streets beneath baskets of ripening fruit. Residents share news on their doorsteps. The civic house stands north, and the inn opens south. The workshops are west.','Living roots brace broad timber halls; growers, hunters and cooks fill the streets beneath baskets of ripening fruit.','{"west": "feastlands-keep-artisan-lane", "north": "feastlands-keep-civic-house", "south": "keep-bunkhouse"}'::jsonb,'road','Orchard Terrace','feastlands-keep') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.rooms (slug,name,description,ambience,exits,kind,label,town_key) VALUES ('feastlands-keep-civic-house','The Harvest House','Living roots brace broad timber halls; growers, hunters and cooks fill the streets beneath baskets of ripening fruit. A clerk records local affairs beside benches where residents discuss work, journeys and grievances. The residential street is south.','Living roots brace broad timber halls; growers, hunters and cooks fill the streets beneath baskets of ripening fruit.','{"south": "feastlands-keep-residential-walk"}'::jsonb,'hall','The Harvest House','feastlands-keep') ON CONFLICT (slug) DO NOTHING;
